/* TNM World Wrestling Report: TWA (Tri-State Wrestling Alliance).
   Everything the site shows for this promotion lives in this file. */

P.twa = {"short": "TWA", "nav": "Tri-State", "name": "Tri-State Wrestling Alliance", "home": "Philadelphia, PA", "c": "var(--twa)", "asOf": "1991-07-19", "status": "Two shows in. Al Snow finally beat Action Jackson, Austin Idol cheated his way past Bob Armstrong, and the Nightstalker is out with a torn biceps just as the first title tournament begins.", "stat": ["$23,400", "gate, 2 shows"], "titles": [["TWA Heavyweight", "VACANT", "Tournament: quarterfinals Trenton 7/27, semifinals Allentown 8/15, final at McGonigle Hall 8/31."], ["TWA Tag Team", "To establish", ""], ["TWA Television", "To establish", ""]], "factions": [["The Office", "Promoter Joel Goodhart, money partner Tod Gordon, booker Austin Idol."], ["Landell & Armstrong", "Buddy Landell and Bob Armstrong, babyfaces. Beat the Bruise Brothers on Show 1. Landell protested Idol's win over Armstrong."], ["The Bruise Brothers", "Ron & Don Harris, splitting time with WCW. 1–1 in the TWA."]], "stories": [["Feet on the Ropes", "Austin Idol said Bigelow \"ran to Japan,\" then pinned Bob Armstrong in Allentown with his feet on the ropes. Buddy Landell protested. The booker won the match."], ["Snow Settles It", "No time limit, no DQ, no count-out: Al Snow pinned Action Jackson with the Snow Plow at 19:30. They shook hands and both pointed at the title tournament."], ["Nightstalker Hurt", "The Nightstalker tore his left biceps beating Bunkhouse Buck. He's out about 7 cards, which is the rest of the summer."], ["Candido Is 2–0", "Chris Candido beat J.T. Smith in the best match in Allentown (***). He's 2–0 and in the tournament."], ["The Title Tournament", "Eight men, three shows, one belt. Idol refuses to enter. Armstrong takes the Nightstalker's spot."], ["Allentown Report", "900 fans in a 1,500-seat hall, $10,800, a **1/4 card and every favorite went over."], ["Idol vs. Bigelow", "The Sizzler main event went to a draw. Bigelow is in Japan until August, and Idol is telling everyone who'll listen that he ran."], ["Bruise Brothers Stumble", "Tapped out on Show 1, won on Show 2 (1/4*). Two TWA matches, two bad ones."]], "earlier": ["twa-snow-vs-jackson", "twa-nightstalker-arrives"], "desk": ["Trenton 7/27 opens the TWA Heavyweight Title tournament: Snow vs. Landell, Candido vs. Sandman, Smith vs. Armstrong, Jackson vs. Bad News Brown.", "The Nightstalker is out about 7 cards (torn left biceps, 7/19), all of July and August. Bob Armstrong takes his tournament spot. The announcers explain it 7/27.", "Austin Idol isn't in the tournament; he's waiting for Bigelow. Idol vs. Landell is the follow-up to the Allentown finish.", "Out for Trenton: Bigelow (New Japan to 7/30), Billy Joe Travis (All Japan), Bruise Brothers (WCW Phoenix 7/27).", "Bruise Brothers: *1/4 and 1/4*. Keep their matches short.", "Wilmington or Newark, DE for 8/2: venue to confirm.", "Re-check August dates against WCW before locking.", "Will TWA become ECW in '92? Still open."], "roster": [["Action Jackson", "11 cards left"], ["Al Snow", "14 cards left"], ["Austin Idol", "11 cards left · booker"], ["Bad News Brown", "11 cards left"], ["Bam Bam Bigelow", "11 cards left · also NJPW, back 8/2"], ["Billy Joe Travis", "11 cards left · also AJPW, out for July"], ["Bob Armstrong", "11 cards left · w/ Landell"], ["Buddy Landell", "11 cards left · w/ Armstrong"], ["Bunkhouse Buck", "11 cards left"], ["Chris Candido", "11 cards left · 2–0"], ["Debbie Combs", "Signed (15 cards)"], ["Debbie Malenko", "Signed (13 cards)"], ["Don Harris", "24 cards left · Bruise Brothers, also WCW"], ["J.T. Smith", "34 cards left"], ["Mr. Sandman", "14 cards left"], ["Reggie Bennett", "Signed (15 cards)"], ["Ron Harris", "24 cards left · Bruise Brothers, also WCW"], ["The Nightstalker", "INJ:Torn left biceps, out ~7 cards"]], "departures": []};

E.push(...[{"d": "1991-06-29", "p": "twa", "city": "Philadelphia, PA", "venue": "McGonigle Hall", "type": "Super Summer Sizzler '91", "gate": "1,180 · ~$12,600", "rate": "**", "big": 1, "link": "SUPER_SU", "m": [["Al Snow vs. Action Jackson", "20:00 draw", "**1/4"], ["The Nightstalker vs. J.T. Smith", "Nightstalker (Meltdown)", "***1/4"], ["Landell & Armstrong vs. Bruise Brothers", "Landell submits R. Harris (Figure Four)", "*1/4"], ["Bad News Brown vs. Bunkhouse Buck", "Brown (powerslam)", "1/2*"], ["Chris Candido vs. Billy Joe Travis", "Candido (waistlock suplex)", "*3/4"], ["Triangle: Austin Idol vs. Bam Bam Bigelow vs. Mr. Sandman", "Draw. Bigelow eliminates Sandman; Idol & Bigelow hit the 20:00 limit", "***"]], "n": ["The TWA debut."], "reads": [["Idol vs. Bigelow", "twa-idol-vs-bigelow"], ["Snow vs. Jackson", "twa-snow-vs-jackson"], ["Nightstalker Arrives", "twa-nightstalker-arrives"], ["Bruise Brothers Stumble", "twa-bruise-brothers-stumble"], ["Observer: Backstage Notes: Super Summer Sizzler", "twa-observer-notes-sizzler"]]}, {"d": "1991-07-19", "p": "twa", "city": "Allentown, PA", "venue": "Agricultural Hall", "type": "Spot show", "gate": "900 · $10,800", "rate": "**1/4", "m": [["Promo: Austin Idol opens the show", "Bigelow \"ran to Japan.\" Armstrong & Landell answer. Idol vs. Armstrong made", ""], ["Chris Candido vs. J.T. Smith", "Candido (pin)", "***"], ["The Nightstalker vs. Bunkhouse Buck", "Nightstalker (Meltdown). Tears left biceps", "*1/2"], ["Bruise Brothers vs. Bad News Brown & Mr. Sandman", "R. Harris pins Sandman (big boot)", "1/4*"], ["Austin Idol vs. Bob Armstrong", "Idol, feet on the ropes. Landell protests", "**3/4"], ["Al Snow vs. Action Jackson II (no time limit, no DQ)", "Snow (Snow Plow), 19:30. Handshake after", "**3/4"]], "n": ["The Nightstalker is out about 7 cards.", "1,500-seat hall, 60% full."], "link": "TSW_AGRI", "reads": [["Snow Settles It", "twa-snow-settles-it"], ["Observer report", "twa-observer-allentown-0719"], ["From the Road: Chris Candido", "twa-diary-candido-0719"], ["Feet on the Ropes", "twa-feet-on-the-ropes"], ["Allentown Report", "twa-allentown-report"], ["Candido Is 2–0", "twa-candido-two-and-oh"], ["Nightstalker Hurt", "twa-nightstalker-hurt"]]}, {"d": "1991-07-27", "p": "twa", "city": "Trenton, NJ", "venue": "CYO Center", "type": "Title tournament quarterfinals", "plan": 1, "m": [["Chris Candido vs. Mr. Sandman", "Candido", ""], ["J.T. Smith vs. Bob Armstrong", "Smith", ""], ["Action Jackson vs. Bad News Brown", "Jackson", ""], ["Al Snow vs. Buddy Landell", "Snow", ""]], "n": ["Out: Bigelow (NJPW), Travis (AJPW), Bruise Brothers (WCW TV), Nightstalker (injured)."]}, {"d": "1991-08-02", "p": "twa", "city": "Wilmington / Newark, DE", "venue": "TBC", "type": "Spot show", "plan": 1, "m": [["Bam Bam Bigelow returns", "Runs Idol off", ""], ["Austin Idol vs. Action Jackson", "", ""]]}, {"d": "1991-08-07", "p": "twa", "city": "Philadelphia, PA", "venue": "McGonigle Hall", "type": "Monthly home show", "plan": 1, "m": [["Bam Bam Bigelow vs. Al Snow", "", ""], ["Landell & Armstrong vs. Bruise Brothers II", "Bruise Brothers", ""], ["Angle: Idol attacks Bigelow", "Rematch signed", ""]]}, {"d": "1991-08-15", "p": "twa", "city": "Allentown, PA", "venue": "Agricultural Hall", "type": "Title tournament semifinals", "plan": 1, "m": [["Chris Candido vs. J.T. Smith", "Candido", ""], ["Al Snow vs. Action Jackson III", "Snow", ""]]}, {"d": "1991-08-23", "p": "twa", "city": "Trenton, NJ", "venue": "CYO Center", "type": "Go-home show", "plan": 1, "m": [["Idol and Bigelow contract signing", "Brawl", ""]]}, {"d": "1991-08-31", "p": "twa", "city": "Philadelphia, PA", "venue": "McGonigle Hall", "type": "Supercard", "big": 1, "plan": 1, "m": [["Austin Idol vs. Bam Bam Bigelow II, no time limit", "Bigelow", ""], ["TWA Heavyweight Title final: Al Snow vs. Chris Candido", "Snow, first champion", ""], ["Bruise Brothers vs. Landell & Armstrong, falls count anywhere", "Bruise Brothers", ""]]}]);

Object.assign(ARTICLES, {"twa-observer-allentown-0719": {"p": "twa", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-20", "region": "Northeast Report", "kicker": "Tri-State · Agricultural Hall, July 19", "title": "Match Observations: Allentown", "dek": "900 in a 1,500-seat hall, a **1/4 card, the tournament favorite hurt, and the booker beats a 51-year-old with his feet on the ropes.", "factTitle": "The Numbers", "facts": [["Venue", "Agricultural Hall, Allentown, PA"], ["Date", "July 19, 1991 · Spot show"], ["Attendance", "900 (about 1,500 capacity)"], ["Average ticket", "$12"], ["Gate", "$10,800"], ["Talent payroll", "About $2,875 (27%)"], ["Card", "**1/4"]], "body": [["p", "The TWA's second show, and first out of Philadelphia, drew 900 to a hall that holds about 1,500 for $10,800. That's a little under the 1,180 and roughly $12,600 the Sizzler did at McGonigle Hall, and it's about what you expect for a new indie's first trip to a new town on a Friday in July. Payroll was about $2,875 for thirteen people, a little over a quarter of the gate, so Joel Goodhart and Tod Gordon made money on the night before the building and the ring truck. The card came in at **1/4, a quarter-star better than the debut."], ["p", "The big story is one nobody in the building knew about until it was over. The Nightstalker tore his left biceps beating Bunkhouse Buck with the Meltdown in 6:53, *1/2. He's expected to be out around seven dates, which for this group is everything through the end of August. That hurts. He had the best match on the debut show and he's on one of the longest deals on the roster. More to the point, people in the office had him as the favorite to win the title tournament. Bob Armstrong takes his spot in the bracket. Whoever wins the belt on 8/31 now has a ready-made first challenger when the Nightstalker comes back in the fall, but only if somebody remembers to do it."], ["p", "Austin Idol opened with a promo saying Bigelow ran to Japan to get away from him. Bigelow is on New Japan's Summer Crush tour and isn't due back until August, so this is the angle while he's gone, and Idol is still one of the best talkers working anywhere. Armstrong and Landell answered him and Idol vs. Armstrong was made on the spot. It went 11:05 at **3/4, and Idol won with his feet on the ropes off a waistlock takedown. Landell got in the referee's face after. Here's the part to keep in mind: Idol is the booker. The booker went over a 51-year-old by cheating. As a heel finish it's fine, it protects Armstrong and it gives Landell and Armstrong a grievance. But Idol has now booked himself into a draw with the biggest star on the roster and a win over the second-biggest name, and he's not in the tournament. The boys notice these things. So far nobody's complaining out loud."], ["p", "Al Snow pinned Action Jackson with the Snow Plow at 19:30 in a no time limit, no DQ, no count-out main, **3/4. Half a star better than their Sizzler draw, though the second half dragged and it didn't need to go twenty. They shook hands after and pointed toward the tournament. The story is simple and it's working: you leave the first match without a finish, you promise the rematch has one, and then it does. Snow is the guy being pushed. He's a good worker who's been overlooked everywhere and he looks like the favorite now that the Nightstalker is out."], ["p", "Chris Candido beat J.T. Smith in 10:05, ***, the best match on the show. That's two shows and two best matches for Smith, both in losses. Candido is 19, works like he's been doing it for ten years and is 2-0. If this promotion is still around in two years, he's a big part of the reason."], ["p", "The Bruise Brothers beat Bad News Brown & Mr. Sandman when Ron Harris pinned Sandman with a big boot in 8:29. It was 1/4*. Their two TWA matches are now *1/4 and 1/4*. They're splitting time with WCW, where they're booked in short matches as monsters, and that's the lesson here too. They're booked against Landell & Armstrong again in August. Keep it to five minutes."], ["p", "Billy Joe Travis is on the All Japan tour and Bigelow's in New Japan, so the group was down two of its names. Nobody's complaining about the house, and the tournament gives the TWA something to sell for six weeks."], ["h", "Results"], ["p", "1. Chris Candido beat J.T. Smith in 10:05. ***"], ["p", "2. The Nightstalker beat Bunkhouse Buck in 6:53 with the Meltdown. The Nightstalker tore his left biceps. *1/2"], ["p", "3. The Bruise Brothers beat Bad News Brown & Mr. Sandman in 8:29 when Ron Harris pinned Sandman with a big boot. 1/4*"], ["p", "4. Austin Idol beat Bob Armstrong in 11:05 with a waistlock takedown and his feet on the ropes. Buddy Landell argued with the referee after. **3/4"], ["p", "5. No time limit, no DQ, no count-out: Al Snow beat Action Jackson in 19:30 with the Snow Plow. Handshake after. **3/4"], ["p", "Overall card: **1/4"], ["p", "Next is the title tournament quarterfinals at the CYO Center in Trenton on 7/27: Candido vs. Sandman, Smith vs. Armstrong, Jackson vs. Bad News and Snow vs. Landell."]]}, "twa-diary-candido-0719": {"p": "twa", "series": "diary", "by": "Chris Candido", "date": "1991-07-19", "place": "Agricultural Hall, Allentown", "kicker": "From the Road · Allentown, July 19", "title": "Chicken Cages and a Title Tournament", "dek": "Chris Candido goes 2-0, watches the Nightstalker come back holding his arm, and heads into a title tournament at 19.", "factTitle": "The Night", "facts": [["Show", "TWA spot show, Agricultural Hall"], ["Match", "Chris Candido d. J.T. Smith"], ["Time", "10:05"], ["Rating", "***"], ["Next", "Mr. Sandman, quarterfinals 7/27"]], "body": [["p", "The Agricultural Hall smells like a county fair, because that's what it is the rest of the year. There were chicken cages stacked behind the curtain. Bunkhouse Buck said he felt right at home. I don't think he was kidding."], ["p", "I had the first match tonight, right after Idol's promo, against J.T. Smith. J.T.'s the best guy in this whole company to be in there with, and I don't care who hears me say it. He bumps for everything. You hit him with a forearm and he flies like you shot him out of a cannon. We went ten minutes and I could feel the crowd coming with us the whole way. When I got the pin they were still clapping for him. That's how you know it was good. 2-0."], ["p", "I came through the curtain and the Nightstalker was going out, and he gave me that look, like good job, kid. Seven minutes later he came back holding his arm against his chest and his face was gray. Torn biceps. He sat on a folding chair with ice on it and didn't say anything for a long time. He was supposed to be the guy in this tournament. Everybody knew it. Now he's out till fall and I'm thinking about what that means for me, and I feel bad for thinking it, and I'm still thinking it."], ["p", "Idol beat Armstrong with his feet on the ropes. Bob came back through and just laughed and said, \"Well, that's the business.\" Buddy Landell wasn't laughing."], ["p", "Snow and Action went almost twenty minutes in the main. They shook hands after and the people stood up. I watched it from the doorway with J.T. and he said that'll be me someday. I said someday's a long time."], ["p", "Sandman in Trenton next week. First round. I'm 19 and they're putting me in a tournament for a title belt. Driving home on 22 with the windows down. My hand still hurts from slapping the mat."]]}, "twa-feet-on-the-ropes": {"p": "twa", "news": 1, "region": "Northeast Report", "by": "Newsletter staff", "date": "1991-07-20", "kicker": "Tri-State · Allentown, July 19", "title": "Feet on the Ropes", "dek": "Austin Idol opened the show by saying Bam Bam Bigelow ran from him, then beat Bob Armstrong with his feet on the ropes. It's worth remembering who books this promotion.", "body": [["p", "The second TWA show, at Agricultural Hall in Allentown on July 19, opened with Austin Idol in the ring and a microphone in his hand. Bigelow, he said, had run to Japan rather than finish what they started at the Sizzler. That's the angle while Bam Bam is on New Japan's Summer Crush tour, and Idol is the right man to sell it. He's been talking people into buildings for twenty years."], ["p", "Bob Armstrong and Buddy Landell came out to answer him, and Idol vs. Armstrong got made on the spot for after intermission. It went 11:05 and got **3/4, which is about as good as either man is going to do in 1991. The finish was the story. Idol pinned Armstrong off a waistlock takedown with his feet on the ropes, the referee didn't see it, and he counted three. Landell, working Armstrong's corner as a babyface, went after the referee about it afterward."], ["h", "The booker wins"], ["p", "Here's the part fans in the building may not know: Idol is the booker. The promotion is Joel Goodhart's, with Tod Gordon putting up money, and Idol is putting the cards together. So the booker put himself over a 51-year-old with his feet on the ropes. That isn't necessarily a bad thing. A cheating heel win is the right finish for a guy who's supposed to be getting heat while his top rival is out of the country, and Idol didn't take a clean win he didn't need. But it's the kind of thing people in the business are going to notice."], ["h", "What it sets up"], ["p", "Armstrong and Landell are now babyfaces with a legitimate grievance. Idol has heat. And Idol has made it clear he's not entering the TWA Heavyweight Title tournament, because the only man he wants is Bigelow. Bigelow is due back in August. If the plan is a big rematch at McGonigle Hall, everything Idol is doing now makes that match bigger, as long as Bigelow doesn't come home and get treated as a sideshow."]], "facts": [["Match", "Austin Idol d. Bob Armstrong"], ["Time", "11:05"], ["Finish", "Waistlock takedown, feet on the ropes"], ["Rating", "**3/4"], ["Protest", "Buddy Landell"], ["Idol's target", "Bam Bam Bigelow"]], "factTitle": "The Finish"}, "twa-snow-settles-it": {"p": "twa", "news": 1, "region": "Northeast Report", "by": "Newsletter staff", "date": "1991-07-20", "kicker": "Tri-State · Allentown, July 19", "title": "Snow Settles It", "dek": "Three weeks after their 20-minute draw, Al Snow and Action Jackson went again with no time limit. This time there was a winner.", "body": [["p", "The main event in Allentown was the rematch of the TWA's first match ever. Al Snow and Action Jackson went 20:00 to a draw at the Sizzler on June 29, and this time the stipulation was no time limit, no count-out and no disqualification. Snow won it at 19:30 with the Snow Plow. It got **3/4, half a star better than the first one."], ["p", "That's the right way to book it. You leave the first match without a finish, you sell the rematch on the idea that somebody has to win, and then somebody wins. Fans who went to both shows got a payoff. That's more than a lot of independents manage."], ["h", "The handshake"], ["p", "After the match, Snow and Jackson shook hands in the ring and both pointed toward the TWA Heavyweight Title tournament, which starts in Trenton on July 27. It was a simple babyface moment, and it was done well. It tells the audience that these two are going to be in the middle of the title picture, and that the series might not be over."], ["p", "Snow is the one getting the push. He's a good worker who's been underused everywhere he's been, and he's now beaten one of his main rivals cleanly in a main event. He draws Buddy Landell in the quarterfinals. Jackson draws Bad News Brown. If both of them win, they're on a collision course in the semifinals in Allentown on August 15. You don't have to be a genius to see where this one is headed."]], "facts": [["Match", "Al Snow d. Action Jackson"], ["Stipulation", "No time limit, no DQ, no count-out"], ["Finish", "Snow Plow, 19:30"], ["Rating", "**3/4"], ["Series", "Snow 1–0–1"], ["Tournament", "Snow vs. Landell, Jackson vs. Bad News (7/27)"]], "factTitle": "The Rematch"}, "twa-nightstalker-hurt": {"p": "twa", "news": 1, "region": "Northeast Report", "by": "Newsletter staff", "date": "1991-07-20", "kicker": "Tri-State · Injury Report", "title": "Nightstalker Hurt", "dek": "The best prospect in the TWA tore his left biceps in a six-minute match with Bunkhouse Buck. He's out for the rest of the summer.", "body": [["p", "The worst news out of Allentown came in the second match of the night. The Nightstalker beat Bunkhouse Buck with the Meltdown at 6:53 and tore his left biceps doing it. The estimate is about seven cards, which for a promotion running roughly once a week means everything the TWA has scheduled through the end of August."], ["p", "It's a real loss. The Nightstalker had the best match on the debut show, a ***1/4 win over J.T. Smith, and he's on one of the longest contracts on the roster. He was positioned as a building block. The word is that the office had big plans for him in the TWA Heavyweight Title tournament, and those plans are now gone."], ["h", "The rebooking"], ["p", "Bob Armstrong takes his spot in the eight-man bracket. Armstrong had just lost to Idol on the same show, so getting him into the tournament gives him something to do besides complain about the feet on the ropes."], ["p", "On television, the story will be that the Nightstalker was hurt on his way into the tournament. That's a good way to handle it. A big man who was supposed to be a contender, who got injured right before his chance, comes back in the fall with a reason to go after whoever ends up holding the belt. A September return as the first challenger to the first champion is a natural story. It's also a story somebody will have to execute."], ["p", "The match itself was *1/2, which isn't surprising for a six-minute match with an injury in it."]], "facts": [["Injury", "Torn left biceps"], ["Match", "d. Bunkhouse Buck, 6:53 (Meltdown)"], ["Out", "About 7 cards, through 8/31"], ["Replacement", "Bob Armstrong, in the tournament"], ["Return", "The fall (expected)"]], "factTitle": "Injury Report"}, "twa-candido-two-and-oh": {"p": "twa", "news": 1, "region": "Northeast Report", "by": "Newsletter staff", "date": "1991-07-20", "kicker": "Tri-State · Match of the Night", "title": "Candido Is 2–0", "dek": "Chris Candido is 19 and he's already one of the best workers on this roster. He beat J.T. Smith in the best match in Allentown and walks into the title tournament undefeated.", "body": [["p", "For the second show in a row, the best match on the TWA card was a midcard singles match. In Allentown it was Chris Candido beating J.T. Smith in 10:05, at ***. Nothing else on the show got higher than **3/4."], ["p", "Candido is the youngest guy on the roster who's getting real minutes, and he works like someone ten years older. He beat Billy Joe Travis with a waistlock suplex at the Sizzler, and that was short and fine at *3/4. This was the real showcase. Smith is a local bumping machine who makes everybody look good, and he lost to the Nightstalker in the best match of the debut show. Now he's had the best match of both shows, in two losses. That should count for something."], ["h", "The tournament"], ["p", "Candido draws Mr. Sandman in the quarterfinals in Trenton on July 27. On paper that's a winnable match. Smith gets Bob Armstrong. If both of them win, they're in a semifinal rematch in Allentown on August 15."], ["p", "If the TWA has a long-term future, Candido is a big part of the reason. He's young, he's good, and he's cheap. He's also on one of the short deals that come up for renewal at the same time as most of the roster, so somebody in the office should be thinking about that."]], "facts": [["Record", "2–0 in the TWA"], ["7/19", "d. J.T. Smith, 10:05, ***"], ["6/29", "d. Billy Joe Travis, 5:08, *3/4"], ["Next", "vs. Mr. Sandman, quarterfinals 7/27"]], "factTitle": "The Rookie"}, "twa-title-tournament": {"p": "twa", "news": 1, "region": "Northeast Report", "by": "Newsletter staff", "date": "1991-07-20", "kicker": "Tri-State · TWA Heavyweight Championship", "title": "The Title Tournament", "dek": "Eight men, three shows, one belt. The TWA will crown its first champion on August 31. The most famous man on the roster isn't entered, and the favorite just got hurt.", "body": [["p", "The Tri-State Wrestling Alliance will crown its first Heavyweight Champion in an eight-man tournament over three shows: the quarterfinals at the CYO Center in Trenton on July 27, the semifinals at Agricultural Hall in Allentown on August 15, and the final at McGonigle Hall in Philadelphia on August 31."], ["h", "The bracket"], ["p", "The quarterfinals: Chris Candido vs. Mr. Sandman, J.T. Smith vs. Bob Armstrong, Action Jackson vs. Bad News Brown, and Al Snow vs. Buddy Landell. Armstrong is in the Nightstalker's spot after the injury in Allentown."], ["h", "Who isn't in it"], ["p", "Austin Idol isn't entered. He says the only thing he cares about is Bam Bam Bigelow, who isn't in it either because he's in Japan. That means the two biggest names in the promotion are outside the title picture, and the first champion will come from the group underneath them. That's a gamble. It's also a way to make a new star instead of putting the belt on a veteran who's passing through."], ["h", "The favorites"], ["p", "Al Snow is the obvious pick. He just beat Action Jackson in a main event and has a clean path to the semifinals, though he'd likely have to go through Jackson again to get to the final. Chris Candido is 2–0 and the best worker in the bracket. Smith keeps having the best match on the card and losing. Bad News Brown is the veteran and, on paper, the toughest out."], ["p", "The best-case scenario for the TWA is Snow vs. Candido in the final: two good workers, both young, one babyface and one who's got the attitude to become something else. The final is on the same card as Idol vs. Bigelow II, if that happens. If the office can get both matches to McGonigle Hall on August 31, it's the biggest show this group has run."]], "facts": [["QF 7/27", "Trenton, CYO Center"], ["SF 8/15", "Allentown, Agricultural Hall"], ["Final 8/31", "Philadelphia, McGonigle Hall"], ["Entrants", "Candido, Sandman, Smith, Armstrong, Jackson, Bad News, Snow, Landell"], ["Not entered", "Austin Idol, Bam Bam Bigelow"]], "factTitle": "The Bracket"}, "twa-allentown-report": {"p": "twa", "news": 1, "region": "Northeast Report", "by": "Newsletter staff", "date": "1991-07-20", "kicker": "Tri-State · Agricultural Hall, Allentown · July 19", "title": "Allentown Report", "dek": "The TWA's first spot show drew 900 to a 1,500-seat hall. It was a better card than the debut, every favorite went over, and the top prospect got hurt.", "body": [["p", "The TWA ran its second show on Friday, July 19 at Agricultural Hall at the Allentown Fairgrounds. It drew 900 in a building that holds about 1,500, at a $12 average ticket, for $10,800. That's a little under the Philadelphia debut (1,180, about $12,600) and about what you'd expect from a new group's first trip out of town. The card rated **1/4, a quarter-star better than the Sizzler."], ["h", "The card"], ["p", "Austin Idol opened with a promo saying Bam Bam Bigelow ran to Japan. Chris Candido beat J.T. Smith (***), the best match of the night. The Nightstalker beat Bunkhouse Buck with the Meltdown (*1/2) and tore his left biceps. The Bruise Brothers beat Bad News Brown and Mr. Sandman when Ron Harris pinned Sandman with a big boot (1/4*). After intermission, Idol beat Bob Armstrong with his feet on the ropes (**3/4). Al Snow pinned Action Jackson with the Snow Plow in a no-DQ, no-time-limit main event (**3/4), and they shook hands after."], ["h", "The Bruise Brothers"], ["p", "The Harris brothers got their win back after tapping on Show 1, but their two TWA matches are now *1/4 and 1/4*. In WCW they're booked as monsters in short squashes, and that's probably the lesson here too. They're cleared for the August TWA dates, and they're booked against Landell and Armstrong again. Keep it short."], ["h", "The verdict"], ["p", "Every match went the way you'd expect, which on an independent card is a sign the booking is working. The main event and the Idol match both told simple stories, Candido had the best match again, and the promotion has a title tournament to sell for the next six weeks. The injury hurts. The house was fine. Next stop is Trenton on July 27."]], "facts": [["Date", "Fri, July 19, 1991"], ["Venue", "Agricultural Hall, Allentown"], ["Crowd", "900 (1,500 capacity)"], ["Gate", "$10,800 · $12 avg"], ["Card rating", "**1/4"], ["Best match", "Candido d. Smith, ***"]], "factTitle": "The Show"}, "twa-observer-notes-sizzler": {"p": "twa", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-06-30", "region": "World Report", "kicker": "Tri-State · Backstage Notes", "title": "Backstage Notes: Super Summer Sizzler", "dek": "The TWA opens at McGonigle Hall, and here is who is running it.", "factTitle": "Filed from", "facts": [["Show", "Super Summer Sizzler '91, 6/29"], ["Attendance", "1,180 (about 1,050 paid)"], ["Card", "**"]], "body": [["h", "McGonigle Hall, Philadelphia"], ["p", "The Tri-State Wrestling Alliance debuted with Super Summer Sizzler '91 before 1,180 fans (about 1,050 paid) at a $12 average ticket, roughly a $12,600 gate. Joel Goodhart is the promoter, Tod Gordon is the money partner, and Austin Idol is booking."]]}, "twa-idol-vs-bigelow": {"p": "twa", "kicker": "Tri-State · Super Summer Sizzler '91 · McGonigle Hall", "title": "Idol vs. Bigelow", "dek": "The new Philadelphia group put its two biggest names in a three-way main event and let them go 20 minutes without a finish. That can be a smart cliffhanger or a waste of a main event, depending on what comes next.", "by": "Northeast report", "date": "1991-07-09", "body": [["p", "The Tri-State Wrestling Alliance ran its first show, Super Summer Sizzler '91, at McGonigle Hall on the Temple campus in Philadelphia. It went six matches, and the card got two stars overall, which is about what you'd expect from a new independent running its first night with a roster pulled from all over the place. No attendance or gate figure has been released, which usually tells you something too."], ["p", "The main event was a triangle match with Austin Idol, Bam Bam Bigelow and Mr. Sandman, and it was the most interesting booking decision on the show. Bigelow eliminated Sandman at 16:04 with Greetings from Asbury Park, his top-rope headbutt, and that left Idol and Bigelow with less than four minutes before the 20:00 time limit. Nobody pinned anybody, the bell rang, and the crowd went home without a winner. It got ***, the second-best match on the card."], ["h", "Why a draw"], ["p", "On paper it makes sense. Idol is the veteran star, a guy fans in this area remember from his Memphis and Florida days, and he can still talk people into a building. Bigelow is the bigger star right now and, frankly, the more valuable piece. He's 30, he's the most athletic big man in the country, and he's spending the summer in Japan on New Japan's Summer Crush tour, where he's been working main events with Riki Chōshu (Korakuen 7/4, Osaka TV 7/6). Neither one of them needed to lose, and a draw protects both."], ["p", "The risk is that a promotion with one show under its belt can't afford many nights where the fans don't get a payoff, and this card had two 20-minute draws, including the opener. Independent fans pay to see something happen. If you're going to send them home without a finish, you'd better have the rematch on the next card or close to it."], ["h", "The Bigelow problem"], ["p", "That's the issue. Bigelow is in Japan for most of July, so a quick rematch probably isn't happening. The expectation is that Idol uses the time to do what he does best and run his mouth: Bigelow left town, Bigelow wouldn't finish it, Bigelow is scared of him. If they handle it right, the absence becomes the angle, and the rematch is a much bigger deal when Bigelow comes home in August."], ["p", "Sandman, meanwhile, was eliminated first and didn't do much. He's a local guy who's still finding his way, and being the first man out in a three-way with two bigger names is about where he belongs at this point. Whether there's more to his character than what we've seen so far is anyone's guess."]], "facts": [["Match", "Triangle: Idol vs. Bigelow vs. Sandman"], ["Elimination", "Bigelow pins Sandman, 16:04"], ["Finish", "Time limit, 20:00"], ["Rating", "***"], ["Card rating", "**"], ["Bigelow", "On NJPW tour in July"]], "factTitle": "The Main Event"}, "twa-snow-vs-jackson": {"p": "twa", "kicker": "Tri-State · The Opener", "title": "Snow vs. Jackson", "dek": "Al Snow and Action Jackson went 20 minutes in the first match ever in the Tri-State Wrestling Alliance and nobody won. It was a decent match. It was also an odd way to start.", "by": "Northeast report", "date": "1991-07-09", "body": [["p", "The first match in TWA history was Al Snow against Action Jackson, and it went the full 20:00 to a draw. It rated **1/4, which isn't bad for an opener on an independent show. The idea of opening the first card of a new promotion with a time-limit draw is a strange one, though."], ["p", "Snow is the one to watch here. He's been kicking around the Midwest indies and is one of the better pure workers on the independent scene, the kind of guy a lot of people in the business think is going to get a real break if somebody figures out what to do with him. Twenty minutes is a long time for an opener, and he made it work well enough that the crowd stayed with it. Jackson kept up. That's a compliment."], ["h", "The booking"], ["p", "Openers are supposed to get the crowd going and give them something to cheer for, and usually that means a finish. A draw in the first match followed by a draw in the main event means two of the six matches on the first show had no winner, and the middle of the card was where all the finishes went. Fans who paid to see the first show ever in this building didn't get to see the first winner until the second match."], ["p", "In fairness, if the plan is to build a Snow vs. Jackson series, this is how you start it. The expectation is a rematch with no time limit at some point, which is the obvious next step and would give the TWA two unfinished feuds going into its second show. That's either good long-term booking or a sign the promotion doesn't trust anybody to lose yet. We'll know more when we see the next card."], ["p", "For what it's worth, Snow is on a slightly longer deal than most of the roster, so he's here for a while if they want him. Jackson is on the same short cycle as most of the crew."]], "facts": [["Match", "Al Snow vs. Action Jackson"], ["Result", "Draw, 20:00 time limit"], ["Rating", "**1/4"], ["Position", "Opener, Show 1"], ["Draws on the card", "2 of 6"]], "factTitle": "The Match"}, "twa-nightstalker-arrives": {"p": "twa", "kicker": "Tri-State · Match of the Night", "title": "Nightstalker Arrives", "dek": "The best match on the first TWA show was a 10-minute singles bout in the middle of the card, and the big man who won it may be the most interesting prospect on the roster.", "by": "Northeast report", "date": "1991-07-09", "body": [["p", "The best match on Super Summer Sizzler wasn't the main event. It was The Nightstalker beating J.T. Smith in 10:11 with a finisher he calls the Meltdown. It got ***1/4, the highest rating on the show, in about half the time of the two draws."], ["p", "That's not an accident. Ten minutes is the right length for a big man's singles match, and Smith is exactly the kind of opponent you want for it. He's a local guy, he bumps all over the place, and he makes the other man look like a killer. Whoever put this match together knew what they were doing."], ["h", "The prospect"], ["p", "The Nightstalker is a big, young heavyweight with a monster look who could be a real asset for this group if they don't waste him. His win was clean, it went over well, and he had the best match on the card without having to be in the main event to do it. That's what you want from a prospect on a first show."], ["p", "It also matters that the TWA has him on one of the longest contracts on the roster. J.T. Smith is on an even longer deal. These are the two guys the company has committed to the most, which suggests the office sees them as building blocks rather than names on a poster. That's a smart way to run an independent, because it means when the touring names leave (and Bigelow and Idol both will, eventually), you have something left."], ["h", "What's next"], ["p", "The obvious next step is a series of wins over the middle of the roster, building to a match with somebody established. A big man with a name, a look and a finisher, beating people clean, is exactly what this promotion needs while its top star is in Japan. Smith, meanwhile, came out of this looking better in defeat than most of the winners on the card did."]], "facts": [["Match", "The Nightstalker vs. J.T. Smith"], ["Winner", "Nightstalker, 10:11"], ["Finish", "The Meltdown"], ["Rating", "***1/4, best on the card"], ["Card rating", "**"]], "factTitle": "Match of the Night"}, "twa-bruise-brothers-stumble": {"p": "twa", "kicker": "Tri-State · Tag Team Division", "title": "Bruise Brothers Stumble", "dek": "In WCW, Ron and Don Harris are being built as unstoppable monsters. In Philadelphia, they tapped to a figure four. Somebody needs to explain that.", "by": "Northeast report", "date": "1991-07-09", "body": [["p", "The strangest result on the first TWA show was in the tag match. Buddy Landell and Bob Armstrong beat the Bruise Brothers when Landell made Ron Harris submit to the figure four leglock at 13:31. It got *1/4, which was generous."], ["p", "The match itself isn't the story. The story is that the Harris brothers are on two rosters at once. In WCW they debuted in Philadelphia at the Civic Center on July 5 with a squash of the Young Pistols, went through Bill Irwin and Butch Reed on TBS in about three minutes, and beat the Killer Bees in Richmond. They're being positioned there as monsters who are about to be recruited into the Dark Circle. And in the same city, in a smaller building, they lost clean to a submission hold."], ["h", "Does it matter?"], ["p", "In 1991 the honest answer is probably not much. Most of the people who watch WCW on TBS will never see a TWA show, and the hardcore fans who see both know the deal. But the Philadelphia market is exactly where those audiences overlap. WCW drew 10,000 at the Civic Center, and the TWA is trying to build a following a few miles away. If the same fans are at both shows, you're asking them to believe two different things about the same team."], ["p", "There are two ways to fix it. The TWA can give the Bruise Brothers the rematch and let them win it decisively, which makes the first loss look like a fluke. Or they can lean into it and make Landell and Armstrong the team that figured out how to beat the monsters, which is a story the TWA can tell and WCW can't. The second option is more interesting. The first one is more likely, given that the Harrises are on longer TWA deals than most of this roster and WCW has bigger plans for them."], ["h", "Landell & Armstrong"], ["p", "Credit to the winners. Landell is a veteran Southern heel who knows how to get heat, and Bob Armstrong has been around forever. They're a thrown-together team, but the figure four is a believable finish and a submission win over the biggest team on the card is a good way to establish yourselves. Whether they're a regular team or just a one-show pairing hasn't been decided."]], "facts": [["Match", "Landell & Armstrong vs. Bruise Brothers"], ["Finish", "Landell submits Ron Harris"], ["Hold", "Figure four leglock, 13:31"], ["Rating", "*1/4"], ["Also in WCW", "Debut 7/5 Philly, 3–0 there"]], "factTitle": "The Tag Match"}});

CONTRACTS.twa = {"basis": "Per show", "unit": "per appearance", "revenue": "Super Summer Sizzler drew about $12,600 and Allentown $10,800: about $11–12K a show.", "target": "About $4,500 a show (40%) across a card of 10–14 workers.", "how": "Base rate for each show worked. The Philadelphia home show and the 8/31 supercard pay 1.25× base, and their main event splits 5% of the gate. Managers and announcers are on the same scale.", "classes": [["Spot show", "Allentown, Trenton, Wilmington", "1×", "—", "—"], ["Philadelphia home show / supercard", "McGonigle Hall, 8/7, 8/31", "1.25×", "5% of gate", "—"]], "rows": [["A", "Bam Bam Bigelow", 600, "Also NJPW"], ["A", "Bad News Brown", 400, ""], ["A", "Austin Idol", 400, "Also the booker"], ["B", "Al Snow", 250, ""], ["B", "Chris Candido", 225, ""], ["B", "Buddy Landell", 225, ""], ["B", "Bob Armstrong", 225, ""], ["C", "Don Harris", 175, "Bruise Brothers, also WCW"], ["C", "Ron Harris", 175, "Bruise Brothers, also WCW"], ["C", "Bunkhouse Buck", 175, ""], ["C", "The Nightstalker", 175, "Injured, torn biceps"], ["C", "Mr. Sandman", 150, ""], ["C", "Action Jackson", 150, ""], ["C", "J.T. Smith", 150, ""], ["C", "Billy Joe Travis", 150, "Also AJPW"], ["O", "TBD: commentator", 50, "Name to be set"], ["O", "TBD: ring announcer", 30, "Name to be set"]], "total": 3705, "check": "At these rates Super Summer Sizzler paid $5,161 (41% of $12,600) and Allentown $2,875 (27% of $10,800)."};

